<?php
require __DIR__.'/_printer_bootstrap.php';$pdo=db();$notice='';$error='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$action=(string)$_POST['action'];if($action==='retry'){KitchenPrinter::attempt($id);$notice='Baskı yeniden denendi.';}elseif($action==='printed'){KitchenPrinter::markPrinted($id);$notice='Baskı tamamlandı olarak işaretlendi.';}elseif($action==='cancel'){$pdo->prepare("UPDATE kitchen_print_jobs SET status='cancelled' WHERE id=? AND status<>'printed'")->execute([$id]);$notice='Baskı iptal edildi.';}}}catch(Throwable $e){$error=$e->getMessage();}
$status=(string)($_GET['status']??'');$allowed=['pending','failed','printed','cancelled'];$where=in_array($status,$allowed,true)?'WHERE j.status='.$pdo->quote($status):'';$jobs=$pdo->query("SELECT j.*,p.name printer_name,p.connection_type FROM kitchen_print_jobs j JOIN kitchen_printers p ON p.id=j.printer_id $where ORDER BY j.id DESC LIMIT 250")->fetchAll();
printer_page_start('Baskı Kuyruğu','queue');?>
<div class="head"><div><span class="eyebrow">GÜVENLİ BASKI AKIŞI</span><h1>Baskı Kuyruğu</h1><p>Başarısız veya manuel bekleyen siparişler kaybolmaz; yeniden yazdırılabilir.</p></div><div class="actions"><a class="btn light" href="?">Tümü</a><a class="btn light" href="?status=pending">Bekleyen</a><a class="btn light" href="?status=failed">Hatalı</a></div></div><?php if($notice):?><div class="notice ok"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="notice err"><?=e($error)?></div><?php endif;?>
<section class="card"><?php if(!$jobs):?><div class="empty">Baskı işi bulunmuyor.</div><?php else:?><table><thead><tr><th>İş</th><th>Yazıcı</th><th>Durum</th><th>Oluşturma</th><th>Hata / Bilgi</th><th>İşlem</th></tr></thead><tbody><?php foreach($jobs as $j):?><tr><td><strong>#<?=$j['id']?> · <?=e($j['title'])?></strong><br><span class="muted">Sipariş #<?=e($j['order_id']??'-')?> · Deneme <?=e($j['attempts'])?></span></td><td><?=e($j['printer_name'])?><br><span class="muted"><?=e($j['connection_type'])?></span></td><td><span class="pill <?=in_array($j['status'],['printed'],true)?'ok':($j['status']==='failed'?'bad':'wait')?>"><?=e(['pending'=>'Bekliyor','printing'=>'Gönderiliyor','printed'=>'Yazdırıldı','failed'=>'Hatalı','cancelled'=>'İptal'][$j['status']]??$j['status'])?></span></td><td><?=e(date('d.m.Y H:i:s',strtotime($j['created_at'])))?></td><td class="muted"><?=e($j['last_error']??'—')?></td><td><div class="actions"><?php if(in_array($j['status'],['pending','failed'],true)):?><a class="btn orange" target="_blank" href="print-job.php?id=<?=$j['id']?>">Aç / Yazdır</a><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="retry"><input type="hidden" name="id" value="<?=$j['id']?>"><button class="btn">Tekrar Dene</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table><?php endif;?></section><?php printer_page_end();
